
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_fr_b88_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_fr_b88", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([9.474603154092118e+01, 9.107646246218800e+01, 8.605766644022687e+01, 7.934280841428657e+01, 7.063674161703517e+01, 5.984330105143119e+01, 4.728414908932031e+01, 3.391493390983705e+01, 2.133591268535080e+01, 1.133420576111176e+01, 5.033120644817764e+00, 2.545568233800343e+00, 1.918892081350331e+00, 1.277132775726297e+00, 6.439879391881943e-01, 2.419072308282290e-01, 6.751583480863337e-02, 1.351993115571236e-02, 1.800380892098771e-03, 1.371632597567918e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


